// "Nebula Drift - Dynamic Cosmic Flow"
// Author: Master Of CP (assisted by Guardian Of Debug)
// Date: September 2024
// Special thanks to: Matteo Basei (Fractal Noise) and Inigo Quilez (Procedural Techniques)

// modified

#define TIME        iTime
#define RESOLUTION  iResolution
#define octaves 7

float random(in vec2 point) {
    return fract(100.0 * sin(point.x + fract(100.0 * sin(point.y))));
}

float noise(in vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    float a = random(i);
    float b = random(i + vec2(1., 0.));
    float c = random(i + vec2(0., 1.));
    float d = random(i + vec2(1., 1.));

    vec2 u = f * f * (3. - 2. * f);

    return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

float fbm(in vec2 p) {
    float value = 0.;
    float freq = 1.;
    float amp = .5;

    for (int i = 0; i < octaves; i++) {
        value += amp * (noise((p - vec2(1.)) * freq));
        freq *= 1.9;
        amp *= .6;
    }

    return value;
}

float pattern(in vec2 p) {
    vec2 offset = vec2(-.5);

    // Using continuous time-based movement with no wrapping
    vec2 aPos = vec2(TIME * 0.025, TIME * 0.05) * 6.0;   // Smooth continuous movement
    vec2 aScale = vec2(6.);   // Increased scale for more details
    float a = fbm(p * aScale + aPos);

    vec2 bPos = vec2(TIME * 0.1, TIME * 0.1) * 1.0;       // Smooth continuous movement
    vec2 bScale = vec2(1.);   // Increased scale for more details
    float b = fbm((p + a) * bScale + bPos);

    vec2 cPos = vec2(-0.6, -0.5) + vec2(TIME * 0.02, TIME * 0.2) * 2.0;  // Smooth continuous movement
    vec2 cScale = vec2(5.);   // Increased scale for more details
    float c = fbm((p + b) * cScale + cPos);

    return c;
}

vec3 palette(in float t) {
    vec3 a = vec3(0.0);       // Base black
    vec3 b = vec3(0.15);      // Slightly dark gray
    vec3 c = vec3(0.8);       // Slightly brighter dark gray
    vec3 d = vec3(0.07);      // Keeps overall tones dark

    return a + b * cos(4.28318 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / RESOLUTION.xy * 2.0 - 1.0;
    uv.x *= RESOLUTION.x / RESOLUTION.y;

    float value = pow(pattern(uv), 2.0);
    vec3 color = palette(value);

    fragColor = vec4(color, 1.0);
}
